mapper.select:
select distinct

from ai_sys_resource
where resourcetype = #{resourceType}
and pid = #{pid}
order by seq

SELECT s.id AS id, s.NAME AS name, s.url AS url, s.description AS description, s.icon AS icon, s.pid AS pid, s.seq AS seq, s. STATUS AS status, s.resourcetype AS resourcetype, s.createdate AS createdate FROM ai_sys_role r LEFT JOIN ai_sys_role_resource e ON r.id = e.role_id LEFT JOIN ai_sys_resource s ON e.resource_id = s.id WHERE r.id=${roleId}
and s.resourcetype = ${resourceType}
AND s.pid = ${pid}
AND s.regroup in (${type},0)
order by pid,seq asc



                   select id,name,url,description,icon,pid,seq,status,resourcetype,createdate
		           from ai_sys_resource
		           where 1=1


                    select a.id,name,url,description,icon,pid,seq,status,resourcetype,createdate
		           from ai_sys_resource a,ai_sys_role_resource_GRANT b
		           where 1=1 and a.id=b.resource_id and role_id=${Roleid}



			and resourcetype = ${resourceType}


			and regroup = ${regroup}
			and pid = ${Pid}



		select id,name,url,description,icon,pid,seq,status,resourcetype,createdate
		from ai_sys_resource
		where 1=1


		select a.id,name,url,description,icon,pid,seq,status,resourcetype,createdate
		from ai_sys_resource a,ai_sys_role_resource_GRANT b
		where 1=1 and a.id=b.resource_id and role_id=${Roleid}



	and resourcetype = ${resourceType}

and pid = ${Pid}

select s.id,s.name,s.url,s.description,s.icon,s.pid,s.seq,s.status,s.resourcetype,s.createdate from ai_sys_resource s
LEFT JOIN ai_sys_role_resource_grant e ON s.id = e.resource_id where 1=1
and e.role_id = ${ParentRole}
and regroup = ${regroup}
and resourcetype = ${resourceType}
and pid is not null order by regroup asc

select
id,name,url,description,icon,pid,seq,status,resourcetype,createdate
from ai_sys_resource
where pid = ${pid}

	and resourcetype = ${resourceType}
